using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class BuildingUiOperations
{
    private async System.Threading.Tasks.Task FrameAfter(Control workspace)
    {var tree=workspace.GetTree();await ToSignal(tree,SceneTree.SignalName.ProcessFrame);if(GodotObject.IsInstanceValid(workspace)&&workspace.IsInsideTree())frame(workspace);}
    private readonly ArchitecturalComponentUi _architecturalUi=new();
    private readonly ModuleLinkUi _moduleUi=new();
    private readonly BuildingStyleOperations _styles=new();
    private static void Status(Control workspace,string text)=>workspace.Get("status").As<Label>().Text=text;
    private void ShowPlan(Control workspace,Resource root,int mode,Action<Control?>? after=null)
    {var job=new BuildingUiPlanJob();workspace.AddChild(job);if(after!=null)job.Connect("completed",Callable.From(()=>after(job.result)));job.start(workspace,"show",root,mode,true,1);}
    private static void PickFile(Control workspace,string kind,string id,int slot=0)
    {var job=new BuildingUiFileJob();workspace.AddChild(job);job.start(workspace,kind,id,slot);}
    public bool properties(Control workspace,Resource item,Node parent)
    {
        if(_architecturalUi.properties(workspace,item,parent))return true;bool moduleProperties=_moduleUi.properties(workspace,item,parent);var session=Session(workspace);var document=session.Get("document").As<Resource>();var root=_buildings.owner(session,item);if(root==null)return moduleProperties;string id=root.Get("id").AsString();var source=this.source(workspace,id)!;var plan=workspace.HasMeta("building_plan")?workspace.GetMeta("building_plan").As<Control>():null;bool hasPlan=GodotObject.IsInstanceValid(plan)&&plan!.Get("building_id").AsString()==id;var floors=source.Get("floors").AsGodotArray();int level=Math.Clamp(hasPlan?plan!.Get("current_floor").AsInt32():0,0,floors.Count-1);var heading=new Label {Text="ARCHITECTURE · "+root.Get("title").AsString()};heading.AddThemeColorOverride("font_color",new Color("8be1ca"));parent.AddChild(heading);var modes=new HBoxContainer();parent.AddChild(modes);bool environment=document.HasMethod("terrain");
        if(document.HasMethod("component_kind")&&document.Call("component_kind",id).AsString()=="building")Button(parent,"Make building detail editable",()=>Apply(workspace,id,this.source(workspace,id)!,"Make building detail editable"));var rootValues=root.Get("parameters").AsGodotDictionary();if(environment&&rootValues.ContainsKey("world_owner")&&rootValues.ContainsKey("world_plot"))Button(parent,"Keep building independent",()=>{string error=GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/world/world_session.gd").Call("keep_independent",Session(workspace),id).AsString();Status(workspace,error.Length>0?error:"Building kept independent of settlement regeneration");});
        var presets=GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/architecture/building_styles.gd").GetScriptConstantMap()["PRESETS"].AsGodotDictionary();var styles=new OptionButton();styles.AddItem("Style · "+source.Get("style").AsString());parent.AddChild(styles);foreach(var name in presets.Keys)styles.AddItem(name.AsString());styles.ItemSelected+=index=>{if(index==0)return;var next=_styles.apply(this.source(workspace,id)!,styles.GetItemText((int)index),presets);if(next!=null)Apply(workspace,id,next,"Apply building style");};var detail=new OptionButton();parent.AddChild(detail);foreach(string name in new[]{"No facade details","Timber frame","Porch","Buttresses","Pilasters","Fins","Cross braces","Spire corners"})detail.AddItem(name);detail.Select(source.Get("facade_detail").AsInt32());detail.ItemSelected+=index=>{var next=_sources.copy(this.source(workspace,id)!);next.Set("facade_detail",index);Apply(workspace,id,next,"Change facade details");};Number(parent,"Detail width",source.Get("detail_width").AsDouble(),.04,.5,.01,value=>{var next=_sources.copy(this.source(workspace,id)!);next.Set("detail_width",value);Apply(workspace,id,next,"Change facade width");});
        if(item.Get("id").AsString()!=id)Button(parent,"Reset procedural overrides on this component",()=>{var result=_buildings.reset_overrides(Session(workspace),id,item.Get("id").AsString());var errors=result["errors"].AsStringArray();Status(workspace,errors.Length>0?errors[0]:"Component reset");});foreach(var entry in new[]{("▦ 2D",0),("◫ Split",1),("◇ 3D",2)}){int mode=entry.Item2;Button(modes,entry.Item1,()=>ShowPlan(workspace,root,mode));}var cut=new CheckButton {Text="Interior cutaway",ButtonPressed=GodotObject.IsInstanceValid(plan)&&plan!.Get("cutaway").AsBool()};parent.AddChild(cut);cut.Toggled+=on=>ShowPlan(workspace,root,1,editor=>{if(editor==null)return;editor.Set("cutaway",on);editor.Call("_apply_cutaway");_ = FrameAfter(workspace);});
        var floorChoice=new OptionButton();parent.AddChild(floorChoice);foreach(var value in floors)floorChoice.AddItem(Get(value.AsGodotDictionary(),"name","Level").AsString());floorChoice.Select(level);floorChoice.ItemSelected+=index=>ShowPlan(workspace,root,1,editor=>{if(editor==null)return;editor.Set("current_floor",index);editor.Set("selected_wall",-1);editor.Set("selected_opening",-1);});Button(parent,"＋ Level",()=>{var next=_sources.copy(this.source(workspace,id)!);var nextFloors=next.Get("floors").AsGodotArray();if(nextFloors.Count>=8){Status(workspace,"This building already has eight levels.");return;}var floor=nextFloors[^1].AsGodotDictionary().Duplicate(true);floor["id"]=Guid.NewGuid().ToString("N");floor["name"]="Level "+(nextFloors.Count+1);floor["elevation"]=floor["elevation"].AsDouble()+Get(floor,"height",3.0).AsDouble();nextFloors.Add(floor);Apply(workspace,id,next,"Add building level");});
        Number(parent,"Level height",Get(floors[level].AsGodotDictionary(),"height",3.0).AsDouble(),1,20,.05,value=>{var next=_sources.copy(this.source(workspace,id)!);var nextFloors=next.Get("floors").AsGodotArray();var floor=nextFloors[level].AsGodotDictionary();double previous=Get(floor,"height",3.0).AsDouble();floor["height"]=value;foreach(var wallValue in floor["walls"].AsGodotArray()){var wall=wallValue.AsGodotDictionary();if(Mathf.IsEqualApprox(Get(wall,"height",previous).AsDouble(),previous))wall["height"]=value;}for(int index=level+1;index<nextFloors.Count;index++){var above=nextFloors[index].AsGodotDictionary();above["elevation"]=above["elevation"].AsDouble()+value-previous;}Apply(workspace,id,next,"Change level height");});
        foreach(var spec in new[]{("Wall thickness","wall_thickness",.02,2.0),("Slab thickness","slab_thickness",.02,1.0),("Foundation depth","foundation_depth",.05,5.0),("Roof pitch","roof_pitch",1.0,75.0),("Roof overhang","roof_overhang",0.0,2.0),("Baseboard height","baseboard_height",0.0,.5),("Crown height","crown_height",0.0,.5),("Interior trim depth","interior_trim_depth",.005,.3)}){string key=spec.Item2,label=spec.Item1;Number(parent,label,source.Get(key).AsDouble(),spec.Item3,spec.Item4,.01,value=>{var next=_sources.copy(this.source(workspace,id)!);next.Set(key,value);Apply(workspace,id,next,"Change "+label.ToLowerInvariant());});}
        var simulation=new CheckButton {Text="Structural physics",TooltipText="Simulate generated walls, floors, doors and supports through the scene timeline. The foundation remains fixed.",ButtonPressed=source.Get("physics_enabled").AsBool()};parent.AddChild(simulation);simulation.Toggled+=on=>{var next=_sources.copy(this.source(workspace,id)!);next.Set("physics_enabled",on);Apply(workspace,id,next,"Change building physics");};var roof=new OptionButton();parent.AddChild(roof);foreach(string name in new[]{"Flat roof","Gable roof","Shed roof","Hip roof"})roof.AddItem(name);roof.Select(source.Get("roof_type").AsInt32());roof.ItemSelected+=index=>{var next=_sources.copy(this.source(workspace,id)!);next.Set("roof_type",index);Apply(workspace,id,next,"Change roof");};
        if(level<floors.Count-1)Button(parent,"＋ Staircase to next level",()=>{var next=_sources.copy(this.source(workspace,id)!);var nextFloors=next.Get("floors").AsGodotArray();next.Get("stairs").AsGodotArray().Add(new Settings {["id"]=Guid.NewGuid().ToString("N"),["from"]=nextFloors[level].AsGodotDictionary()["id"],["to"]=nextFloors[level+1].AsGodotDictionary()["id"],["type"]=0,["position"]=new Vector2(-1,-2),["width"]=1.0,["length"]=4.0,["steps"]=16});Apply(workspace,id,next,"Add staircase");});for(int index=0;index<source.Get("stairs").AsGodotArray().Count;index++)stair_properties(workspace,id,source,index,parent);int selected=hasPlan?plan!.Get("selected_wall").AsInt32():-1;if(selected>=0&&selected<floors[level].AsGodotDictionary()["walls"].AsGodotArray().Count)wall_properties(workspace,id,source,level,selected,plan!.Get("selected_opening").AsInt32(),parent);
        foreach(var entry in new[]{("Exterior wall material",0),("Interior wall material",5),("Floor material",1),("Ceiling material",6),("Roof material",2),("Trim / door material",3),("Glass material",4)}){int slot=entry.Item2;Button(parent,entry.Item1+"…",()=>PickFile(workspace,"material",id,slot));}Button(parent,"＋ Insert model / furniture…",()=>PickFile(workspace,"module",item.Get("id").AsString()));Button(parent,"⌖ Align component anchors…",()=>anchors(workspace,item.Get("id").AsString()));if(environment)FoundationProperties(workspace,root,parent);LayoutProperties(workspace,root,source,parent);return true;
    }
}
